# More detailed marker analysis for cluster assignment
import pandas as pd
import numpy as np
import scipy.sparse

# Extended marker panel
extended_markers = {
    'T_cells': ['CD3D', 'CD3E', 'CD4', 'CD8A', 'CD8B', 'CD28', 'TRAC', 'TRBC1'],
    'NK_cells': ['NKG7', 'GNLY', 'KLRD1', 'FCGR3A', 'NCOR1', 'GZMB'],
    'B_cells': ['CD19', 'CD79A', 'CD79B', 'MS4A1', 'MZB1', 'BANK1'],
    'Monocytes_Macrophages': ['CD14', 'CD68', 'FCGR3A', 'SPP1', 'CSF1R', 'CD163', 'LYZ'],
    'DCs': ['CD1C', 'FCN3', 'HLA-DRA', 'HLA-DPA1', 'HLA-DPB1', 'CD1A', 'CD1B'],
    'Fibroblasts': ['DCN', 'COL1A1', 'COL3A1', 'THY1', 'PDGFRA', 'LUM']
}

print("=== EXTENDED MARKER EXPRESSION BY CLUSTER ===")
all_markers = []
for cell_type, markers in extended_markers.items():
    all_markers.extend(markers)

present_markers = [m for m in all_markers if m in adata.var_names]

marker_expr = {}
for marker in present_markers:
    gene_idx = adata.var_names.tolist().index(marker)
    for cluster in sorted(adata.obs['leiden'].unique()):
        cluster_cells = adata.obs[adata.obs['leiden'] == cluster].index
        marker_adata = adata[cluster_cells, [marker]]
        if scipy.sparse.issparse(marker_adata.X):
            mean_val = np.array(marker_adata.X.mean(axis=0)).flatten()[0]
        else:
            mean_val = np.mean(marker_adata.X)[0]
        if marker not in marker_expr:
            marker_expr[marker] = {}
        marker_expr[marker][cluster] = mean_val

# Create a table organized by cell type
for cell_type, markers in extended_markers.items():
    present_cell_markers = [m for m in markers if m in present_markers]
    if len(present_cell_markers) > 0:
        table_data = []
        for marker in present_cell_markers:
            row = [marker] + [f"{marker_expr[marker][c]:.4f}" for c in sorted(adata.obs['leiden'].unique())]
            table_data.append(row)

        table = pd.DataFrame(table_data, columns=['Gene'] + [str(c) for c in sorted(adata.obs['leiden'].unique())])
        print(f"\n{cell_type}:")
        print(table.to_string(index=False))
